    ('17', '01', '164', '296',
     'MARRIAGE AND FAMILY THERAPIST', 'An individual who provides marriage and family therapy services to individuals, couples and families and evaluates and treats mental and emotional problems within the context of human relationships.',
     '0', '2', '2', '1', '0',
     '2', '0', '9', 'G', '0',
     'https://www.idfpr.com/', '20240905'),
    ('17', '01', '165', '165',
     'RADIATION THERAPIST', 'A person, other than a licensed practitioner, who performs procedures and applies ionizing radiation emitted from X-ray machines, particle accelerators, or sealed radioactive sources to human beings for therapeutic purposes while under the supervision of a licensed practitioner.',
     '0', '9', '9', '9', '0',
