     '0', '20220617'),
    ('23', '01', '008080', '008',
     'Forester, Registered Professional', 'Foresters offer professional services requiring the application of forestry principles and techniques, including investigations, consultations, development of forest management plans, supervision of forest management, forest utilization, forest economics or other forestry activities carried out in connection with public or private lands.',
     '1', '2', '1', '0', '2',
     '9', '0', '9', '9', '0',
     '0', '20220617'),
    ('23', '01', '008081', '008',
