     '4', '20220621'),
    ('23', '01', '008127', '008',
     'Manufactured Housing Mechanic', 'Manufactured housing mechanics install, repair, and replace units, fixtures, appliances, and other items and systems in mobile and modular homes, prefabricated buildings, or travel trailers using hand tools or power tools.',
     '0', '1', '0', '0', '0',
     '9', '0', '9', '9', '0',
