     '2', '0', '9', '9', '0',
     '0', '20220617'),
    ('23', '01', '008133', '008',
     'Nursing Home Administrator', 'Nursing home administrators supervise, plan, develop, monitor and maintain appropriate standards of care throughout all departments in the nursing home.',
     '1', '2', '1', '0', '0',
     '2', '0', '9', '9', '0',
     '0', '20220617'),
    ('23', '01', '008134', '008',
     'Nursing Home Administrator, Temporary', 'Nursing home administrators supervise, plan, develop, monitor and maintain appropriate standards of care throughout all departments in the nursing home. Temporary licenses are valid for 90 days.',
