     '3', '20220622'),
    ('23', '01', '026009', '026',
     'Medical Doctor, Consultive Telemedicine', 'This is for physicians who will be providing consultative telemedicine and not physically practicing in the state.',
     '2', '2', '1', '1', '2',
     '2', '0', '9', '9', '0',
     '0', '20220622'),
    ('23', '01', '026010', '026',
     'Physician Assistant', 'This license is for physician assistants who will be working with physicians who hold a permanent license.',
     '2', '2', '1', '1', '2',
     '2', '0', '9', '9', '0',
     '0', '20220622'),
    ('23', '01', '026012', '026',
     'Physician Assistant, Non-Clinical', 'This license is for physician assistants who hold a license but do not have a current certificate of registration or primary supervising physician that is registered with the board. This license does not allow for the rendering of medical services or the prescribing of medications.',
     '2', '2', '1', '1', '2',
