    ('35', '01', 'R48D', 'R48',
     'Body Art Apprentice', 'License to practice body art in New Mexico while participating in an apprenticeship program.',
     '4', '1', '1', '1', '0',
     '0', '4', '0', '9', '0',
     'https://www.rld.nm.gov/boards-and-commissions/individual-boards-and-commissions/body-art-practitioners-overview/', '20240905'),
    ('35', '01', 'R48E', 'R48',
     'Body Art Apprentice Sponsor', 'License to teach a body art apprenticeship program in New Mexico.',
     '4', '1', '1', '1', '0',
     '2', '4', '0', '9', '0',
     'https://www.rld.nm.gov/boards-and-commissions/individual-boards-and-commissions/body-art-practitioners-overview/', '20240905'),
    ('35', '01', 'swn60', 'R25',
     'Licensed Clinical Social Worker', NULL,
