     '9', '9', '9', '9', '0',
     'https://ride.ri.gov/teachers-administrators/educator-certification-0', '20230810'),
    ('44', '01', 'ADM0001430', 'EDU',
     'School Business Administrator', 'Valid for service as an administrator of business and finance in the public schools under rules and regulations of the State Board of Regents.',
     '0', '9', '9', '9', '0',
     '9', '0', '9', '9', '0',
     'https://ride.ri.gov/teachers-administrators/educator-certification-0', '20230810'),
    ('44', '01', 'ALR0000010', 'HPR',
     'Assisted Living Residence Administrator', 'Responsible for the day to day adminstration or operation of an assisted living residence.',
