     'https://firesafety.vermont.gov/licensing', '20230908'),
    ('50', '01', 'anesthasst', 'he4',
     'Anesthesiologist Assistant, Certified', 'Administers anesthetics (any agent that causes unconsciousness or insensitivity to pain) under the direction and supervision of an anesthesiologist.',
     '0', '2', '2', '1', '0',
     '2', '2', '0', '9', '0',
